func CanonicalURL(input string) (string, error) {
    raw := strings.TrimSpace(input)
    if raw == "" { return "", err("path required") }
    if strings.Contains(raw, "\\") || strings.Contains(raw, "%") { return "", err("invalid path") }
    if i := strings.IndexByte(raw, '#'); i >= 0 { raw = raw[:i] }
    if i := strings.IndexByte(raw, '?'); i >= 0 { raw = raw[:i] }
    lower := strings.ToLower(raw)
    var path string
    if strings.HasPrefix(lower, "https://") || strings.HasPrefix(lower, "http://") || strings.HasPrefix(raw, "//") {
        rest := raw
        if strings.HasPrefix(lower, "https://") { rest = raw[8:] } else if strings.HasPrefix(lower, "http://") { rest = raw[7:] } else { rest = raw[2:] }
        slash := strings.IndexByte(rest, '/')
        hostport := rest
        path = "/"
        if slash >= 0 { hostport = rest[:slash]; path = rest[slash:] }
        if strings.Contains(hostport, "@") { return "", err("userinfo not allowed") }
        if strings.Contains(hostport, ":") { return "", err("port not allowed") }
        if strings.ToLower(hostport) != host { return "", err("host not allowed") }
    } else if strings.HasPrefix(raw, "/") {
        path = raw
    } else {
        path = "/" + raw
    }
    for strings.Contains(path, "//") { path = strings.ReplaceAll(path, "//", "/") }
    path = strings.ToLower(path)
    for _, seg := range strings.Split(path, "/") {
        if seg == "." || seg == ".." { return "", err("path traversal") }
    }
    if len(path) > 1 { path = strings.TrimRight(path, "/") }
    if path == "" { path = "/" }
    if _, ok := paths[path]; !ok { return "", err("unknown path: " + path) }
    if path == "/" { return Origin + "/", nil }
    return Origin + path, nil
}

func resolve(name string) (string, error) {
    if v, ok := pages[name]; ok { return v, nil }
    if v, ok := blogs[name]; ok { return v, nil }
    if _, ok := basePaths[name]; ok { return name, nil }
    return "", err("unknown page: " + name)
}

func HomeURL() string { u, _ := CanonicalURL("/"); return u }
func PageURL(name string) (string, error) { p, e := resolve(name); if e != nil { return "", e }; return CanonicalURL(p) }
func BlogURL(slug string) (string, error) {
    v, ok := blogs[slug]
    if !ok { return "", err("unknown blog: " + slug) }
    return CanonicalURL(v)
}
func LocaleURL(locale, name string) (string, error) {
    if _, ok := locales[locale]; !ok { return "", err("unknown locale: " + locale) }
    p, e := resolve(name)
    if e != nil { return "", e }
    if locale == "en" { return CanonicalURL(p) }
    if p == "/" { return CanonicalURL("/" + locale) }
    return CanonicalURL("/" + locale + p)
}

type pathError string
func (e pathError) Error() string { return string(e) }
func err(s string) error { return pathError(s) }
